function useFetchUser(userId, setUser, setLoading) {
  useEffect(() => {
    setLoading(true);
    fetch(`/api/users/${userId}`)
      .then(res => res.json())
      .then(data => {
        setUser(data);
        setLoading(false);
      });
  }, [userId, setUser, setLoading]);
}

