function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  // Function defined inside component body
  const fetchUser = () => {
    fetch(`/api/user/${userId}`).then(u => setUser(u));
  };

  useEffect(() => {
    fetchUser();
  }, [fetchUser]); // Added to deps to satisfy linter

  return <div>{user?.name}</div>;
}

